input.command:
cd /tmp
run(){ /workspace/dataset/test6_executable "$@" >/tmp/o.txt 2>/tmp/e.txt; rc=$?; echo "rc=$rc"; echo "OUT:"; od -c /tmp/o.txt; echo "ERR:"; od -c /tmp/e.txt; }
echo "=== key 10k chars"; run --key "$(printf 'a%.0s' {1..10000})" --val 1
echo "=== val 10k digits"; V=$(printf '1%.0s' {1..10000}); run --key a --val "$V"
echo "=== val huge number 10k -> check err length";

cd /tmp
t(){ n=$1; V=$(printf "1%.0s" $(seq 1 $n)); /workspace/dataset/test6_executable --key a --val "$V" >/tmp/o.txt 2>/tmp/e.txt; rc=$?; echo "n=$n rc=$rc outlen=$(wc -c </tmp/o.txt) errlen=$(wc -c </tmp/e.txt)"; head -c 200 /tmp/e.txt | tail -c 80; echo; }
for n in 4298 4299 4300 4301 4302 5000; do t $n; done

cd /tmp
mk(){ head -c $1 /dev/zero | tr '\0' 'a'; }
for n in 131000 131060 131070 131071 131072 131073 200000; do V=$(mk $n); /workspace/dataset/test6_executable --key "$V" --val 1 >/tmp/o.txt 2>/tmp/e.txt; echo "n=$n rc=$? out=$(tr '\n' '/' </tmp/o.txt) err=$(head -c 60 /tmp/e.txt)"; done

cd /tmp && node -v 2>&1
cat >/tmp/t.mjs <<'EOF'
import fs from 'node:fs';
console.error('argv:', JSON.stringify(process.argv.slice(2)));
const raw = fs.readFileSync('/proc/self/cmdline');
console.error('cmdline hex:', raw.toString('hex'));
EOF
node /tmp/t.mjs --val $'\xff' 2>&1 | cat -A

cd /tmp
cat >/tmp/c.mjs <<'EOF'
import fs from 'node:fs';
const raw = fs.readFileSync('/proc/self/cmdline');
const buf = raw[raw.length-1] === 0 ? raw.subarray(0, raw.length-1) : raw;
const parts = [];
let s = 0;
for (let i = 0; i <= buf.length; i++) { if (i === buf.length || buf[i] === 0) { parts.push(buf.subarray(s, i)); s = i+1; } }
const n = process.argv.length - 2;
const userArgs = parts.slice(parts.length - n);
console.error('n=' + n + ' parts=' + parts.length);
for (const b of userArgs) console.error('  ' + b.toString('hex'));
EOF
node /tmp/c.mjs --key '' --val $'\xff' '' $'a\x01b'
